   600   * Get the vertices of a pentagon cell as substrate FaceIJK addresses
   601   *
   602   * @param fijk The FaceIJK address of the cell.
   603   * @param res The H3 resolution of the cell. This may be adjusted if
   604   *            necessary for the substrate grid resolution.
   605   * @param fijkVerts Output array for the vertices
   606   */
   607  void _faceIjkPentToVerts(FaceIJK *fijk, int *res, FaceIJK *fijkVerts) {
   608      // the vertexes of an origin-centered pentagon in a Class II resolution on a
   609      // substrate grid with aperture sequence 33r. The aperture 3 gets us the
   610      // vertices, and the 3r gets us back to Class II.
   611      // vertices listed ccw from the i-axes
   612      CoordIJK vertsCII[NUM_PENT_VERTS] = {
   613          {2, 1, 0},  // 0
   614          {1, 2, 0},  // 1
   615          {0, 2, 1},  // 2
   616          {0, 1, 2},  // 3
   617          {1, 0, 2},  // 4
   618      };
   619
   620      // the vertexes of an origin-centered pentagon in a Class III resolution on
   621      // a substrate grid with aperture sequence 33r7r. The aperture 3 gets us the
   622      // vertices, and the 3r7r gets us to Class II. vertices listed ccw from the
   623      // i-axes
   624      CoordIJK vertsCIII[NUM_PENT_VERTS] = {
   625          {5, 4, 0},  // 0
   626          {1, 5, 0},  // 1
   627          {0, 5, 4},  // 2
   628          {0, 1, 5},  // 3
   629          {4, 0, 5},  // 4
   630      };
   631
   632      // get the correct set of substrate vertices for this resolution
   633      CoordIJK *verts;
   634      if (isResolutionClassIII(*res))
   635          verts = vertsCIII;
   636      else
   637          verts = vertsCII;
   638
   639      // adjust the center point to be in an aperture 33r substrate grid
   640      // these should be composed for speed
   641      _downAp3(&fijk->coord);
   642      _downAp3r(&fijk->coord);
   643
   644      // if res is Class III we need to add a cw aperture 7 to get to
   645      // icosahedral Class II
   646      if (isResolutionClassIII(*res)) {
   647          _downAp7r(&fijk->coord);
   648          *res += 1;
   649      }
